<template>
  <div class="flex flex-col gap-4">
    <SubcontractorCompanySubcanvassersFilters :params="params" />
    <Card>
      <AppLoader v-if="isLoading" subject="subcontractor canvassers" variant="inline" />
      <AppError v-else-if="error" :error="error" title="Failed to load subcontractor canvassers" variant="table" />
      <ResponsiveTable v-else-if="data && data.items.length > 0" rounded>
        <ResponsiveTableHeader>
          <ResponsiveTableHead>Name</ResponsiveTableHead>
          <ResponsiveTableHead>Email</ResponsiveTableHead>
          <ResponsiveTableHead>Phone</ResponsiveTableHead>
        </ResponsiveTableHeader>
        <ResponsiveTableBody>
          <ResponsiveTableRow
            v-for="sub in data.items"
            :key="sub.id"
            :to="{ name: 'users-id', params: { id: sub.id } }"
          >
            <ResponsiveTableCell :cols="4" :cols-sm="4" label="Name">
              <div class="flex items-center gap-3">
                <Avatar size="sm">
                  <AvatarFallback class="uppercase">
                    {{ sub.first_name.charAt(0) }}{{ sub.last_name.charAt(0) }}
                  </AvatarFallback>
                </Avatar>
                <span class="font-medium line-clamp-1">{{ sub.first_name }} {{ sub.last_name }}</span>
              </div>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="2" label="Email">
              <span class="text-sm break-all">
                {{ sub.email }}
              </span>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="2" label="Phone">
              <span class="text-sm">{{ sub.phone }}</span>
            </ResponsiveTableCell>
          </ResponsiveTableRow>
        </ResponsiveTableBody>
        <ResponsiveTableFooter :colspan="4" :cols="4" :cols-sm="4">
          <AppPagination
            :page="params.page || 1"
            :size="params.size || 10"
            :total="data.total_count"
            label="subcontractor canvassers"
          />
        </ResponsiveTableFooter>
      </ResponsiveTable>
      <AppEmpty v-else subject="subcontractor canvassers" variant="table" />
    </Card>
  </div>
</template>

<script setup lang="ts">
import {
  getSubcontractorCompanySubcanvasserList,
  type GetSubcontractorCompanySubcanvasserListData,
  type GetSubcontractorCompanySubcanvasserListResponse,
  type SortType,
  type SubcontractorCompanySubcanvasserSortBy,
} from '~/client';

definePageMeta({
  backGroup: 'subcontractor-company',
  roles: ['admin'],
  backLabel: 'subcontractor company',
});

defineOptions({ inheritAttrs: false });

const route = useRoute('subcontractor-companies-id-subcanvassers');
const companyId = computed(() => route.params.id);

const params = computed((): NonNullable<GetSubcontractorCompanySubcanvasserListData['query']> => {
  const queryParams = {
    ...parsePagination(route.query),
    sort_type: (route.query.sort_type as SortType) || 'asc',
    sort_by: (route.query.sort_by as SubcontractorCompanySubcanvasserSortBy) || 'name',
    search_query: (route.query.search_query as string) || undefined,
  };

  return Object.fromEntries(Object.entries(queryParams).filter(([_, value]) => value !== undefined)) as NonNullable<
    GetSubcontractorCompanySubcanvasserListData['query']
  >;
});

const { data, error, isLoading } = useQuery({
  key: () => ['subcontractor-company-subcanvassers', companyId.value, params.value],
  query: (): Promise<GetSubcontractorCompanySubcanvasserListResponse> =>
    getSubcontractorCompanySubcanvasserList({
      composable: '$fetch',
      path: { subcontractor_company_id: companyId.value },
      query: ref(params.value),
    }),
  enabled: () => route.name === 'subcontractor-companies-id-subcanvassers' && !!companyId.value,
});
</script>
